SourceCode.Declaration:
/// <summary>
/// Holds the per-order evaluation result produced by <c>ABR_SalesOrderReleaseAgent</c>.
/// </summary>
internal final class ABR_SalesOrderReleaseResult
{
    private SalesId       salesId;
    private boolean       released;
    private str           reservationStatus;
    private str           shippingAdvice;
    private str           errorReason;

}

Method.Source:
/// <summary>Gets the sales order number.</summary>
public SalesId salesId()
{
    return salesId;
}

/// <summary>Sets the sales order number.</summary>
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

/// <summary>Returns <c>true</c> when the order was successfully released.</summary>
public boolean released()
{
    return released;
}

/// <summary>Sets the released flag.</summary>
public boolean parmReleased(boolean _released = released)
{
    released = _released;
    return released;
}

/// <summary>Returns the human-readable reservation status ("Full", "Partial", "None").</summary>
public str reservationStatus()
{
    return reservationStatus;
}

/// <summary>Sets the reservation status label.</summary>
public str parmReservationStatus(str _reservationStatus = reservationStatus)
{
    reservationStatus = _reservationStatus;
    return reservationStatus;
}

/// <summary>Returns the human-readable shipping advice ("Complete", "Partial").</summary>
public str shippingAdvice()
{
    return shippingAdvice;
}

/// <summary>Sets the shipping advice label.</summary>
public str parmShippingAdvice(str _shippingAdvice = shippingAdvice)
{
    shippingAdvice = _shippingAdvice;
    return shippingAdvice;
}

/// <summary>Returns the error reason when evaluation could not be completed.</summary>
public str errorReason()
{
    return errorReason;
}

/// <summary>Sets the error reason.</summary>
public str parmErrorReason(str _errorReason = errorReason)
{
    errorReason = _errorReason;
    return errorReason;
}

/// <summary>Creates a new instance.</summary>
public static ABR_SalesOrderReleaseResult construct()
{
    return new ABR_SalesOrderReleaseResult();
}
